"""Build the static client review website from shared components and one form master."""
from pathlib import Path
from html import escape as e
import json,re

ROOT=Path(__file__).parent
C=json.loads((ROOT/'site-config.json').read_text(encoding='utf-8'))
A=C['audiences']
REVIEW_Q='?v='+C['reviewVersion'] if C.get('reviewVersion') else ''
PAGES={
'client':dict(title='Consulting expertise for your business | OptimIQ Consultus',description='Find assessed consultants, strategic advisors and project managers. Discuss your project or explore an optional fee comparison.',eyebrow='FOR ORGANISATIONS & BUSINESS LEADERS',headline='Experienced consultants for critical business projects.',intro='Access independently assessed consultants, strategic advisors and project managers. Work with proven talent under clear, agreed terms, supported by initial project scoping.',primary='Discuss a Project Requirement',secondary='Compare Project Fees',film='How OptimIQ helps you find the right expertise.',takeaways=[('Assessed talent','Experience and completed work are reviewed before introduction.'),('Scoping support','A Solution Coordinator helps clarify initial requirements.'),('Flexible working models','On-site, remote or hybrid arrangements are agreed in advance.')],overview='OptimIQ helps you define the expertise your project needs. Consultants and firms are assessed, and a Solution Coordinator supports initial requirements and routing. Working arrangements, scope and payment terms are agreed for each engagement. Optional Project Success Management provides agreed delivery oversight.',faqs=[('How are consultants assessed?','Assessment considers domain capability, behaviour under pressure, stakeholder navigation and outcome ownership. Relevant experience and past work support the evaluation.'),('Who supports project delivery?','A Solution Coordinator supports initial scoping and onboarding. Optional Project Success Management provides delivery oversight under an agreed scope and terms.'),('How are fees and payments agreed?','Rates, project stages and payment schedules are agreed in advance. Terms may include mobilisation payments; completed milestones follow review and the agreed contract.'),('Can consultants work on-site or remotely?','On-site, remote and hybrid arrangements depend on the project requirement and consultant availability.'),('How is sensitive project information handled?','Our team discusses suitable safeguards before sensitive information is shared. Please keep confidential documents out of the initial enquiry.')]),
'expert':dict(title='Independent consulting opportunities | OptimIQ Consultus',description='Apply to OptimIQ as a consultant, strategic advisor or project manager. Explore assessment and an optional earnings example.',eyebrow='FOR CONSULTANTS, STRATEGIC ADVISORS & PROJECT MANAGERS',headline='Great work should not depend on a famous employer.',intro='OptimIQ evaluates your experience and completed project results. Apply to be considered for consulting opportunities across the Gulf and internationally.',primary='Apply to Join OptimIQ',secondary='View Earnings Example',film='Independent evaluation and relevant opportunities.',takeaways=[('Evaluated delivery','Your experience and completed project results inform assessment.'),('Verified capability','Evidence and professional discussion support evaluation.'),('Relevant matching','Opportunities depend on capability, availability and client demand.')],overview='Begin with registration. Email verification and a private profile follow through the approved onboarding process. Your experience, evidence and professional discussion inform quality review. Assessed standing and relevant matching depend on evaluation and client demand; application does not guarantee certification or work.',faqs=[('What do I need for the initial application?','Choose Consultant, Strategic Advisor or Project Manager, then complete the same fields as the existing registration form. Contact details, expertise, availability and evidence depend on your chosen role.'),('Does applying guarantee certification or projects?','No. Assessed standing depends on evaluation and supporting evidence. Project opportunities depend on client requirements, relevant capability and availability.'),('Are my identity and contact details public?','They remain private during matching. Any identifying introduction follows the approved platform process and required terms.'),('Do I have to share my earnings example?','No. The calculator is optional. Its commercial figures are included only when you confirm the calculation and separately choose to attach it.'),('What happens after I apply?','The application is recorded through the production service. Email verification and the private evidence step follow the approved onboarding process. The team will explain any further requirements.')]),
'firm':dict(title='Consulting firm partnerships | OptimIQ Consultus',description='Explore independent assessment, specialist capacity and relevant opportunities while keeping your consulting firm’s identity.',eyebrow='FOR BOUTIQUE & MID-SIZED CONSULTING FIRMS',headline='Compete on merit. Win larger business projects.',intro='Explore independent assessment and additional specialist capacity while keeping your firm’s identity. Relevant opportunities depend on client requirements and consultant availability.',primary='Discuss a Firm Partnership',secondary='Estimate Missed Opportunities',film='How OptimIQ helps your practice scale.',takeaways=[('Independent evaluation','Firm capabilities and relevant evidence inform assessment.'),('Additional specialist capacity','Explore expertise to support an agreed requirement, subject to availability.'),('Your firm’s identity','Keep your firm’s identity when you pursue opportunities through OptimIQ.')],overview='Start with a partnership enquiry. The team explores your firm’s capabilities, practice coverage and intended collaboration. Assessment and relevant availability support matching to client requirements. Keep your firm’s identity when you pursue opportunities through OptimIQ. Delivery arrangements and commercial terms are agreed for each engagement.',faqs=[('Will our firm keep its identity?','Yes. You keep your firm’s identity when you pursue opportunities through OptimIQ. Client introductions follow agreed platform terms.'),('Are individual practitioners assessed?','Individual practitioners may follow the appropriate quality assessment process. Firm assessment, practitioner assessment and commercial agreements are distinct activities.'),('Does assessment guarantee introductions?','No. Eligibility depends on verified capabilities, relevant availability and client requirements. Opportunities and capacity are not guaranteed.'),('Can we seek projects and additional capacity?','Yes. You may express interest in new project opportunities, additional consultant capacity, or both. Neither choice is required for the initial enquiry.'),('Is an NDA already in place when we enquire?','An initial enquiry does not itself put an NDA in force. Discuss appropriate arrangements before sharing confidential client records or proprietary firm information.')])}

# Feedback 1: client-supplied calculator copy; preserve the approved page components.
for a in A:
 PAGES[a].update(headline=A[a]['title'],intro=A[a]['calculatorIntro'],primary=A[a]['action'],secondary='Explore the estimate')

def route(a,prefix=''):
 return prefix+A[a]['route']+'/'+REVIEW_Q
def action(a,label=None,prefix='',current='home',klass='button'):
 href=('#'+A[a]['formAnchor']) if current in ('home',a) else route(a,prefix)+'#'+A[a]['formAnchor']
 return f'<a class="{klass}" href="{href}" data-register="{a}">{e(label or A[a]["action"])} <span aria-hidden="true">↗</span></a>'
def brand(prefix):
 return f'<a class="brand" href="{prefix}index.html{REVIEW_Q}" aria-label="OptimIQ Consultus home"><img src="{prefix}../public-website/assets/OptimIQ_Short_logo.png" width="44" height="44" alt=""><span><b>OptimIQ</b><small>Consultus</small></span></a>'
def member_login(current,prefix=''):
 audience={'client':'client','expert':'consultant','firm':'consulting-firm'}.get(current)
 return prefix+'../'+C['publicLinks']['memberPortalPreview']+('?'+'audience='+audience if audience else '')

def header(current,prefix):
 links=''.join(f'<a href="{route(a,prefix)}"'+(' aria-current="page"' if a==current else '')+f'>{e("For "+A[a]["name"].lower())}</a>' for a in A)
 opts=''.join(action(a,{'client':'I need consulting expertise','expert':'I am a consultant or advisor','firm':'I lead a consulting firm'}[a],prefix,current,'') for a in A)
 return f'<a class="skip" href="#main">Skip to content</a><header class="header"><div class="wrap header-inner"><button class="nav-toggle" id="nav-toggle" type="button" aria-label="Open menu" aria-expanded="false" aria-controls="public-navigation"><svg viewBox="0 0 24 24" width="22" height="22" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><path class="menu-lines" d="M4 6h16M4 12h16M4 18h16"/><path class="menu-close" d="m6 6 12 12M18 6 6 18"/></svg></button>{brand(prefix)}<nav id="public-navigation" aria-label="Main navigation">{links}<a href="{prefix}index.html{REVIEW_Q}#why-optimiq">Why OptimIQ</a><a class="member-login" href="{member_login(current,prefix)}">Member login</a></nav><div class="register-menu"><button id="register-toggle" aria-expanded="false" aria-controls="register-options">Register <span aria-hidden="true">↗</span></button><div id="register-options" hidden>{opts}</div></div></div></header>'
def social_icon(name):
 paths={
 'linkedin':'<path d="M5 8.5v11M5 4.5v.1M10 19.5v-11h4v1.6c.8-1.1 1.7-1.9 3.2-1.9 2.4 0 3.8 1.5 3.8 4.5v6.8M14 13v6.5"/>',
 'instagram':'<rect x="3" y="3" width="18" height="18" rx="5"/><circle cx="12" cy="12" r="4"/><path d="M17.5 6.5h.01"/>',
 'x':'<path d="M4 3h4l12 18h-4L4 3Zm0 18 7-8M20 3l-7 8"/>'}
 return '<svg viewBox="0 0 24 24" width="19" height="19" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths[name]+'</svg>'

def footer(prefix,current):
 d=C['contact']
 links=''.join(f'<a href="{route(a,prefix)}">For {e(A[a]["name"].lower())}</a>' for a in A)
 socials=''.join((f'<a href="{e(x["url"])}" target="_blank" rel="noopener noreferrer" aria-label="OptimIQ on {e(x["label"])} (opens in a new tab)">{social_icon(x["id"])}</a>' if x.get('url') else f'<span class="social-pending" role="img" aria-label="{e(x["label"])} — coming soon" title="{e(x["label"])} — coming soon">{social_icon(x["id"])}</span>') for x in d['socials'])
 social_note='<small class="social-note">Social profiles coming soon.</small>' if not any(x.get('url') for x in d['socials']) else ''
 emails=''.join(f'<div class="contact-channel"><span>{e(x["label"])}</span><a href="mailto:{e(x["address"])}">{e(x["address"])}</a></div>' for x in d['emails'])
 presence=''.join(f'<li>{e(x)}</li>' for x in d['presence'])
 addresses=''.join(f'<address>{e(x)}</address>' for x in d.get('officeAddresses',[]))
 return f'<div class="footer-surface"><footer class="wrap footer" id="contact" aria-label="Contact and useful links"><div class="footer-brand">{brand(prefix)}<div class="social-links" aria-label="Social media">{socials}</div>{social_note}</div><div class="footer-links"><h2>Explore</h2>{links}<a href="{member_login(current,prefix)}">Member login</a><a href="{prefix}index.html{REVIEW_Q}#enquiries">General enquiries</a></div><div class="footer-contact"><h2>Contact OptimIQ</h2><a class="contact-phone" href="{e(d["phone"]["href"])}">{e(d["phone"]["label"])}</a>{emails}</div><div class="footer-presence"><h2>Our presence</h2><ul>{presence}</ul>{addresses}</div><div class="footer-bottom"><small>© 2026 OptimIQ Consultus</small><button class="policy-link" type="button">Privacy Notice</button></div></footer></div>'

def field(f,a):
 name=f['name'];label=e(f['label']);ident=f'{a}-{name}';req=' required' if f.get('required') else '';mark='<span aria-hidden="true">*</span>' if req else '<small>(optional)</small>';typ=f.get('type','text')
 attrs=f'id="{ident}" name="{name}" aria-describedby="{ident}-hint {ident}-error"'+req
 if typ in ('practice','role','experience'):
  choices=C['practiceAreas'] if typ=='practice' else [{'id':x,'label':x} for x in C['roles' if typ=='role' else 'experienceBands']]
  control=f'<select {attrs}><option value="">Select {"a practice area" if typ=="practice" else "a role" if typ=="role" else "your experience"}</option>'+''.join(f'<option value="{e(x["id"])}">{e(x["label"])}</option>' for x in choices)+'</select>'
 elif typ=='textarea':control=f'<textarea {attrs} maxlength="{f["max"]}" rows="3"></textarea>'
 else:control=f'<input {attrs} type="{typ}"'+(f' minlength="{f["min"]}"' if f.get('min') else '')+(f' maxlength="{f["max"]}"' if f.get('max') else '')+(f' autocomplete="{f["autocomplete"]}"' if f.get('autocomplete') else '')+'>'
 return f'<label class="form-field" for="{ident}">{label} {mark}{control}<span class="field-hint" id="{ident}-hint">{e(f.get("hint",""))}</span><span class="field-error" id="{ident}-error" hidden></span></label>'
def cta_field(f,prefix):
 name=f['name'];ident=f'{prefix}-{name}';kind=f['type'];required=f.get('required');req=' required' if required else '';mark=' <span class="required-mark" aria-hidden="true">*</span>' if required else '';pending=f.get('needsClarification');label=e(f['label']);options=f.get('options',[])
 described=f' aria-describedby="{ident}-hint {ident}-error"';disabled=' disabled' if pending else ''
 if kind in ('checkboxes','radios'):
  controls=''.join(f'<label class="check-line"><input type="{"checkbox" if kind=="checkboxes" else "radio"}" name="{name+("[]" if kind=="checkboxes" else "")}" value="{e(o["value"])}"><span>{e(o["label"])}</span></label>' for o in options)
  if pending:controls='<p class="field-hint">Choices need clarification.</p>'
  multi=f.get('presentation')=='multiselect' and not pending
  if multi:controls=f'<details class="cta-multiselect" data-multi-select><summary data-multi-summary data-placeholder="{e(f.get("placeholder") or "Select options")}">{e(f.get("placeholder") or "Select options")}</summary><div class="cta-options">{controls}</div></details>'
  else:controls=f'<div class="cta-options">{controls}</div>'
  return f'<fieldset class="cta-choice-field{(" cta-multiselect-field" if multi else "")}" id="{ident}" data-choice-field="{name}" data-required="{str(bool(required)).lower()}" data-pending="{str(bool(pending)).lower()}"{described}><legend>{label}{mark}</legend>{controls}<span class="field-hint" id="{ident}-hint">'+('Needs clarification: the existing form has no selectable options.' if pending else '')+f'</span><span class="field-error" id="{ident}-error" hidden></span></fieldset>'
 attrs=f'id="{ident}" name="{name}"{described}{req}{disabled}'
 if kind=='select':
  control=f'<select {attrs}><option value="">{e("Choices need clarification" if pending else f.get("placeholder") or "Select an option")}</option>'+''.join(f'<option value="{e(o["value"])}">{e(o["label"])}</option>' for o in options)+'</select>'
 elif kind=='textarea':control=f'<textarea {attrs} rows="4" placeholder="{e(f.get("placeholder") or "")}"></textarea>'
 elif kind=='file':
  control=f'<input {attrs} type="file" accept="{e(f["accept"])}"'+(' multiple' if f.get('multiple') else '')+f' data-max-files="{f.get("maxFiles",1)}" data-max-bytes="{f.get("maxBytes",0)}"><div class="file-selection" data-file-selection></div>'
 else:control=f'<input {attrs} type="{kind}" placeholder="{e(f.get("placeholder") or "")}"'+(' autocomplete="email"' if kind=='email' else ' autocomplete="name"' if name=='full_name' else ' autocomplete="tel"' if kind=='tel' else '')+'>'
 hint='Needs clarification: the existing form has no selectable options.' if pending else f.get('hint') or ('PDF, DOC, DOCX · Max 5 files' if kind=='file' and f.get('multiple') else 'PDF, DOC, DOCX · Up to 5 MB' if kind=='file' and f.get('maxBytes') else '')
 return f'<div class="form-field{(" full-width" if kind in ("textarea","file") else "")}" data-cta-field="{name}" data-pending="{str(bool(pending)).lower()}"><label for="{ident}">{label}{mark}</label>{control}<span class="field-hint" id="{ident}-hint">{e(hint)}</span><span class="field-error" id="{ident}-error" hidden></span></div>'
def cta_sections(sections,prefix):
 return ''.join(f'<section class="cta-form-section"><h3>{e(s["heading"])}</h3><p class="cta-section-note">{e(s["description"])}</p><div class="form-grid">'+''.join(cta_field(f,prefix) for f in s['fields'])+'</div></section>' for s in sections)
def form(a,current,drawer=False):
 login_href=member_login(a,'' if current=='home' else '../')
 d=A[a];title={'client':'Tell Us What You Need','expert':'Build Your Verified Professional Profile','firm':'Partner with OptimIQ'}[a]
 intro={'client':'Share the challenge, capability, or project need in a few clear steps.','expert':'Choose the role that best represents your expertise, then complete the profile that matches your experience and availability.','firm':'Tell us how your firm wants to work with OptimIQ.'}[a]
 close='<button class="close-button" type="button" data-close-form>Close ×</button>' if drawer else ''
 if a=='expert':
  tabs='<div class="cta-role-tabs" role="tablist" aria-label="Professional role">'+''.join(f'<button type="button" role="tab" id="cta-role-{i}" data-cta-role="{role}" aria-selected="{str(i==0).lower()}" aria-controls="cta-panel-{i}" tabindex="{0 if i==0 else -1}">{role}</button>' for i,role in enumerate(C['roles']))+'</div>'
  content=tabs+'<input type="hidden" name="role" value="Consultant">'+''.join(f'<fieldset class="cta-role-panel" role="tabpanel" id="cta-panel-{i}" aria-labelledby="cta-role-{i}" data-cta-role-panel="{role}"'+(' hidden disabled' if i else '')+'>'+cta_sections(d['roleProfiles'][role]['sections'],f'expert-{i}')+'</fieldset>' for i,role in enumerate(C['roles']))
 else:content=cta_sections(d['sections'],a)
 attach='<label class="check-line attachment-choice"><input name="attach_earnings_calculation" type="checkbox" disabled><span>Attach my confirmed earnings calculation (optional)</span></label><p class="attachment-help">You can register without a calculation. Confirm the calculation to enable this option.</p>' if a=='expert' else '<p class="attachment-help">You can continue without a calculation.</p>'
 draft='<button class="button secondary" type="button" data-save-draft>Save as Draft</button>' if a=='expert' else ''
 return f'<section class="registration-panel {"home-drawer" if drawer else "audience-form"}" id="{d["formAnchor"]}" data-form-section="{a}" aria-labelledby="{a}-form-heading" {"hidden" if drawer else ""}><form data-contact-form="{a}" novalidate><div class="form-heading"><div><p class="eyebrow">REGISTRATION</p><h2 id="{a}-form-heading" tabindex="-1">{title}</h2></div>{close}</div><p class="form-intro">{intro}</p><p class="registration-signin">Already registered? <a href="{login_href}">Member login</a></p><div class="error-summary" role="alert" hidden></div>{content}<div class="attachment"><div class="scenario-summary" hidden><div><strong>Calculation attached</strong><p></p></div><button type="button" class="text-link" data-remove-scenario>Remove</button></div>{attach}</div><p class="form-privacy">We handle your information in accordance with our <button class="policy-link" type="button">Privacy Notice</button>. Files selected in this review stay in your browser and are not uploaded.</p><div class="honeypot" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="form-bottom">{draft}<button class="button" type="submit" disabled>{d["submit"]} <span aria-hidden="true">↗</span></button><p class="preview-note">Review preview · no information is sent.</p></div><p class="draft-status" role="status"></p><div class="submit-status" role="status" tabindex="-1"></div><div class="form-confirmation" tabindex="-1" hidden><h3></h3><p></p></div></form></section>'

def numeric(a,f):
 name=f['name'];ident=f'{a}-{name}-number';value=f['default'];values=f.get('values',[]);isdiscrete=f.get('discrete');lo=0 if isdiscrete else f.get('min',0);hi=len(values)-1 if isdiscrete else f.get('max',100);step=1 if isdiscrete else f.get('step',1);pos=values.index(value) if isdiscrete else value
 if f.get('choices'):
  controls='<fieldset class="growth-choice"><legend class="sr-only">'+e(f['label'])+'</legend>'+''.join(f'<label><input type="radio" data-calc-input="{name}" name="{a}-{name}" value="{v["value"]}" '+('checked' if v['value']==value else '')+f'>{e(v["label"])}</label>' for v in f['choices'])+'</fieldset>'
 elif isdiscrete:
  controls=f'<div class="slider-input"><input type="range" min="0" max="{hi}" step="1" value="{pos}" data-calc-range="{name}" aria-label="{e(f["label"])} slider"><select id="{ident}" data-calc-input="{name}" aria-label="{e(f["label"])} in USD">'+''.join(f'<option value="{v}" '+('selected' if v==value else '')+f'>${v:,}</option>' for v in values)+'</select></div>'
 else:controls=f'<div class="slider-input"><input type="range" min="{lo}" max="{hi}" step="{step}" value="{value}" data-calc-range="{name}" aria-label="{e(f["label"])} slider"><input id="{ident}" type="number" min="{lo}" max="{hi}" step="{step}" value="{value}" data-calc-input="{name}" inputmode="numeric" required aria-label="{e(f["label"])}" aria-describedby="{a}-{name}-error"></div>'
 label=f'<span>{e(f["label"])}</span>' if f.get('choices') else f'<label for="{ident}">{e(f["label"])}</label>'
 hint='<p class="field-note">30 represents 30 or more years.</p>' if name=='years' else ''
 return f'<div class="tool-field"><div class="field-heading">{label}<span>{f["unit"]}</span></div>{controls}{hint}<label class="check-line input-confirm"><input type="checkbox" data-confirm="{name}" aria-label="Confirm {e(f["label"].lower())}"><span>Confirm this value</span><small data-confirm-state="{name}">Example</small></label><p class="field-error" id="{a}-{name}-error" data-calc-error="{name}" hidden></p></div>'
def calculator(a,current,home=False):
 d=A[a];anchor=d['homeToolAnchor'] if home else d['toolAnchor']
 close='<button class="close-button" type="button" data-close-tool>Close ×</button>' if home else '<span class="optional-label">Optional tool</span>'
 confirm='Confirm calculation to attach (optional)' if a=='expert' else 'Confirm figures and attach to enquiry'
 return f'<section id="{anchor}" class="tool-panel" data-calculator="{a}" aria-labelledby="{a}-calculator-heading" {"hidden" if home else ""}><div class="tool-heading"><div><p class="eyebrow">YOUR POSSIBILITIES WITH OPTIMIQ</p><h2 id="{a}-calculator-heading" tabindex="-1">{d["title"]}</h2></div>{close}</div><p class="calculator-intro">{e(d["calculatorIntro"])}</p><div class="tool-layout"><div class="tool-inputs">'+''.join(numeric(a,f) for f in d['inputs'])+f'</div><div class="tool-result"><span class="result-state">Based on example figures</span><p class="result-verdict"></p><strong class="result-total"></strong><h3></h3><div class="result-details"></div><p class="result-note"></p>{action(a,d["action"],current=current)}{concept_button(a,"calculator")}<button class="text-link confirm-calculation" type="button" data-confirm-calculation>{confirm} <span aria-hidden="true">→</span></button></div></div><p class="sr-only" data-result-announcement aria-live="polite" aria-atomic="true"></p><p class="tool-bottom" data-remaining>Example figures are shown. Confirm the displayed figures only if they reflect your chosen scenario.</p></section>'
def video(current,prefix):
 home=current=='home';p=None if home else PAGES[current];heading='See how OptimIQ works.' if home else p['film'];overview='OptimIQ connects organisations with assessed consultants and consulting firms. A Solution Coordinator supports scoping and routing. Optional Project Success Management provides agreed delivery oversight. Scope, stages and payment terms, including any mobilisation payments, are agreed for each engagement.' if home else p['overview']
 takeaways=[(x['title'],x['text']) for x in C['assurance']['points']] if home else p['takeaways']
 actions=''.join(action(a,None,prefix,current,'action-line') for a in A) if home else action(current,PAGES[current]['primary'],prefix,current)
 return f'<section class="wrap video-section" id="video"><div class="section-heading"><p class="eyebrow">THE BIG PICTURE</p><h2 data-core>{heading}</h2></div><div class="video-layout"><div class="film-module" data-film="{current}"><video controls playsinline preload="none" aria-label="{e(heading)}" hidden></video><button class="video-poster" data-play aria-controls="film-fallback" aria-expanded="false"><img src="{prefix}../public-website/assets/collaboration.jpg" width="1800" height="1202" alt="" loading="lazy"><span class="poster-title">{heading}</span><span class="play-icon" aria-hidden="true">▶</span><span class="poster-caption">Explainer preview</span></button><div id="film-fallback" class="video-fallback" role="status" hidden><strong>This film is not available yet.</strong><p>Read the overview below or continue with your enquiry.</p><button class="text-link" data-retry-video type="button">Try playback again ↗</button></div><details class="transcript"><summary>Read the overview <span aria-hidden="true">+</span></summary><p>{overview}</p></details></div><aside class="video-aside"><p class="eyebrow">YOUR NEXT STEP</p><h3>{"Choose what comes next." if home else "Start with a conversation."}</h3><p>Continue when you are ready. Watching the film is optional.</p>{actions}</aside></div><div class="takeaways" id="{("why-optimiq" if home else "video-takeaways")}">'+(f'<p class="eyebrow">{e(C["assurance"]["eyebrow"])}</p><h3 class="takeaway-heading">{e(C["assurance"]["heading"])}</h3>' if home else '')+'<div class="trust-grid">'+''.join(f'<article><span class="trust-icon" aria-hidden="true">{i+1:02}</span><h3 data-core>{e(t)}</h3><p data-core>{e(s)}</p></article>' for i,(t,s) in enumerate(takeaways))+'</div></div></section>'
def rolecards(selectable=False):
 roles=[('Consultant','Hands-on expertise for defined business workstreams.'),('Strategic Advisor','Experienced guidance for senior commercial and organisational decisions.'),('Project Manager','Coordination of teams, milestones and project progress.')]
 return '<div class="role-cards">'+''.join(f'<article class="role-card"><span class="role-index">0{i+1}</span><h3 data-core>{r}</h3><p data-core>{s}</p>'+ (f'<button class="text-link" type="button" data-role-card="{r}" aria-pressed="false" aria-label="Choose {r} as your professional role">Choose role <span aria-hidden="true">→</span></button>' if selectable else '')+'</article>' for i,(r,s) in enumerate(roles))+'</div>'
def practice():return '<div class="practice-grid">'+''.join(f'<div><span aria-hidden="true">{i+1:02}</span><h3>{e(x["label"])}</h3></div>' for i,x in enumerate(C['practiceAreas']))+'</div>'
def journey(items):return '<ol class="journey-steps">'+''.join(f'<li><span aria-hidden="true">{i+1:02}</span><strong data-core>{e(s)}</strong></li>' for i,s in enumerate(items))+'</ol>'
def faq(a):return '<section class="wrap content-section faq-section" id="faqs"><div class="section-heading"><p class="eyebrow">GOOD TO KNOW</p><h2>Frequently asked questions</h2></div><div class="faqs">'+''.join(f'<article><h3><button class="faq-toggle" aria-expanded="false" aria-controls="faq-{i}">{e(q)}<span aria-hidden="true">+</span></button></h3><div class="faq-answer" id="faq-{i}" hidden><p>{e(ans)}</p></div></article>' for i,(q,ans) in enumerate(PAGES[a]['faqs']))+'</div></section>'
def guide(a):
 # One shared email-only dialog is rendered in the shell for all audience entry points.
 return ''
def concept_button(a,context,klass='text-link'):
 if not C['guides'][a] or not C['guides'][a].get('approved') or not C['guides'][a].get('url'):return ''
 return f'<button class="{klass} concept-note-trigger" type="button" data-concept-note="{a}" data-note-source="{context}" aria-haspopup="dialog">Get the concept note <span aria-hidden="true">↓</span></button>'
def concept_dialog():
 return '<dialog id="concept-note-dialog" aria-labelledby="concept-note-heading" aria-describedby="concept-note-description"><form id="concept-note-form" novalidate><div class="form-heading"><div><p class="eyebrow">OPTIMIQ CONSULTUS · PDF</p><h2 id="concept-note-heading">Get the concept note</h2></div><button class="close-button" type="button" data-close-note aria-label="Close concept note">Close ×</button></div><p id="concept-note-description">Enter your email address to download your copy.</p><label class="note-email-label" for="concept-note-email">Email address <span aria-hidden="true">*</span><input id="concept-note-email" name="email" type="email" autocomplete="email" maxlength="254" required aria-describedby="concept-note-email-error" placeholder="you@company.com"><span class="field-error" id="concept-note-email-error" hidden></span></label><p class="form-privacy">We handle your information in accordance with our <button class="policy-link" type="button">Privacy Notice</button>.</p><div class="honeypot" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="note-actions"><button class="button" type="submit">Download PDF <span aria-hidden="true">↓</span></button><p class="preview-note" data-note-preview>Review simulator · your email is not saved.</p></div><p class="submit-status" role="status" aria-live="polite" data-note-status></p><a class="text-link" data-note-download download hidden>Download your PDF again <span aria-hidden="true">↓</span></a></form></dialog>'
def general():
 fields=[dict(name='full_name',label='Full name',required=True,min=2,max=160,autocomplete='name'),dict(name='email',label='Email address',required=True,type='email',max=254,autocomplete='email'),dict(name='organisation',label='Organisation',max=200,autocomplete='organization'),dict(name='phone',label='Phone or WhatsApp',type='tel',max=60,autocomplete='tel')]
 return '<section class="wrap enquiries" id="enquiries"><div class="enquiry-top"><div><h2>General questions?</h2><p>For media, institutional collaboration and general correspondence.</p></div><button id="enquiry-toggle" class="text-link" aria-expanded="false" aria-controls="general-form">Send us a message <span aria-hidden="true">↗</span></button></div><form class="general-form" id="general-form" data-contact-form="general" novalidate hidden><div class="form-heading"><h3 tabindex="-1" id="general-form-heading">Send us a message</h3><button class="close-button" type="button" id="enquiry-close">Close ×</button></div><div class="error-summary" role="alert" hidden></div><div class="form-grid">'+''.join(field(f,'general') for f in fields)+field(dict(name='category',label='Enquiry type',required=True),'general').replace('<input id="general-category" name="category" aria-describedby="general-category-hint general-category-error" required type="text">','<select id="general-category" name="category" aria-describedby="general-category-hint general-category-error" required><option value="">Choose a topic</option><option>General enquiry</option><option>Media and press</option><option>Institutional collaboration</option><option>Other</option></select>')+field(dict(name='message',label='Message',required=True,type='textarea',min=10,max=2000),'general')+'</div><label class="check-line"><input type="checkbox" name="privacy_acknowledgement" required aria-describedby="general-privacy-error"><span>I acknowledge the <button class="policy-link" type="button">Privacy Notice</button>.</span><span class="field-error" id="general-privacy-error" hidden></span></label><div class="honeypot" aria-hidden="true"><label>Leave this field empty<input name="website" tabindex="-1" autocomplete="off"></label></div><div class="form-bottom"><button class="button" type="submit" disabled>Send Message <span aria-hidden="true">↗</span></button><p class="preview-note">Review preview · no information is sent.</p></div><div class="submit-status" role="status" tabindex="-1"></div><div class="form-confirmation" tabindex="-1" hidden><h3></h3><p></p></div></form></section>'
def shell(current,body):
 prefix='' if current=='home' else '../';page=PAGES.get(current,{});title=page.get('title','OptimIQ Consultus — Expertise for your next step');desc=page.get('description','Explore consulting expertise, independent opportunities and firm partnerships with OptimIQ Consultus.')
 return f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><meta name="theme-color" content="#0F172A"><meta name="description" content="{e(desc)}"><title>{e(title)}</title><link rel="preload" href="{prefix}assets/Inter-Variable.ttf" as="font" type="font/ttf" crossorigin><link rel="preload" href="{prefix}assets/PlusJakartaSans-Variable.ttf" as="font" type="font/ttf" crossorigin><link rel="stylesheet" href="{prefix}site.css?v=mobile-menu-1"><script src="{prefix}site-config.js?v=mobile-menu-1" defer></script><script src="{prefix}benchmark-preview.js?v=mobile-menu-1" defer></script><script src="{prefix}public-core.js?v=mobile-menu-1" defer></script><script src="{prefix}submission-service.js?v=mobile-menu-1" defer></script><script src="{prefix}site.js?v=mobile-menu-1" defer></script></head><body data-page="{current}">{header(current,prefix)}<main id="main">{body}</main><div id="mobile-registration" class="mobile-registration" hidden><a class="button" id="mobile-register-action" href="#">Register <span aria-hidden="true">→</span></a></div>{footer(prefix,current)}{concept_dialog()}<dialog id="policy-dialog" aria-labelledby="policy-title"><div class="form-heading"><h2 id="policy-title">Privacy Notice</h2><form method="dialog"><button class="close-button">Close ×</button></form></div><p>The final Privacy Notice will be available before these forms open for submissions. This review preview does not send or save your information.</p></dialog><noscript><p class="wrap">Enable JavaScript to try the optional calculators and form preview. Audience pages remain available through the navigation links.</p></noscript></body></html>'

def build_home():
 questions={a:A[a]['title'] for a in A}
 blurbs={'client':'See how much value you could keep by engaging seasoned experts directly.','expert':'See what verified projects could add to your year and where you could start.','firm':'See what you could win back as a partner firm, with no extra fixed payroll.'}
 buttons={'client':'Explore Project Value','expert':'Explore Earnings Potential','firm':'Explore Partnership Potential'}
 direct={'client':'Discuss a project directly','expert':'Apply as a consultant directly','firm':'Discuss a partnership directly'}
 cards=''.join(f'<article class="audience-card" id="{a}-card"><p class="eyebrow">0{i+1} / FOR {A[a]["name"].upper()}</p><h2>{questions[a]}</h2><p>{blurbs[a]}</p><button class="button" data-tool="{a}" aria-expanded="false" aria-controls="{A[a]["homeToolAnchor"]}">{buttons[a]} <span aria-hidden="true">↗</span></button>{action(a,direct[a],klass="text-link")}<div class="card-resources"><a class="learn-more" href="{route(a)}" aria-label="Learn more for {A[a]["name"].lower()}">Learn more <span aria-hidden="true">→</span></a>{concept_button(a,"audience-card")}</div></article>' for i,a in enumerate(A))
 hero='<section class="hero"><div class="wrap"><div class="hero-top"><div><p class="eyebrow">CONSULTING EXPERTISE, CONNECTED.</p><h1>The success of your project<br> depends on the <span>people who deliver it.</span></h1><p class="hero-intro">OptimIQ connects organisations with assessed consultants and consulting firms. Find the right expertise and agree clear project terms.</p></div><span class="hero-flourish" aria-hidden="true">↗</span></div><div class="audience-cards">'+cards+'</div><div id="tools">'+''.join(calculator(a,'home',True) for a in A)+'</div><div id="registration-drawers">'+''.join(form(a,'home',True) for a in A)+'</div><div class="hero-bottom"><span>Three perspectives. One connected network.</span><a href="#video">See how OptimIQ works <span aria-hidden="true">↓</span></a></div></div></section>'
 closing='<section class="wrap closing"><div><p class="eyebrow">LET’S MOVE FORWARD</p><h2>Ready to take<br> the next step?</h2></div><div class="closing-actions">'+''.join(action(a,{'client':'Register your interest','expert':'Apply to join','firm':'Discuss a partnership'}[a],klass='button'+(' secondary' if a!='client' else '')) for a in A)+'</div></section>'
 (ROOT/'index.html').write_text(shell('home',hero+video('home','')+closing+general()),encoding='utf-8')
def build_audience(a):
 p=PAGES[a];d=A[a];hero=f'<section class="audience-hero wrap" id="top"><p class="eyebrow">{p["eyebrow"]}</p><h1 data-core>{p["headline"]}</h1><p class="audience-intro" data-core>{p["intro"]}</p><div class="hero-actions">{action(a,p["primary"],"../",a)}<a class="button secondary" href="#{d["toolAnchor"]}" data-tool="{a}">{p["secondary"]} <span aria-hidden="true">↓</span></a>{concept_button(a,"audience-hero")}</div></section>'
 if a=='client':
  before='<section class="section-band"><div class="wrap content-section" id="team-model"><p class="eyebrow">BUILT AROUND YOUR REQUIREMENT</p><h2 data-core>Flexible team structures for your business goals.</h2><p class="section-intro" data-core>Build the team around the skills, location and time commitment your project needs.</p><div class="team-panels"><article><span class="panel-overline">ON THE GROUND</span><h3 data-core>Regional expertise</h3><p data-core>Consultants for agreed on-site needs and local working context.</p></article><article><span class="panel-overline">CONNECTED ACROSS BORDERS</span><h3 data-core>International specialists</h3><p data-core>Targeted remote contributions for defined areas of expertise.</p></article></div><p class="small-note">Illustrative arrangements, subject to the agreed requirement and availability.</p></div></section>'
  after='<section class="wrap content-section" id="roles"><p class="eyebrow">THE RIGHT CONTRIBUTION</p><h2 data-core>Expertise for the work ahead.</h2>'+rolecards()+'</section><section class="section-band"><div class="wrap content-section" id="practice-areas"><p class="eyebrow">AREAS OF EXPERTISE</p><h2>Recognise your business challenge.</h2>'+practice()+'</div></section>'
 elif a=='expert':
  before='<section class="section-band"><div class="wrap content-section" id="roles"><p class="eyebrow">YOUR PROFESSIONAL PATH</p><h2 data-core>Choose the contribution you want to make.</h2><p class="section-intro" data-core>Explore the role that reflects your experience. Complete the matching registration form below.</p>'+rolecards(True)+journey(['Application','Profile and evidence','Professional discussion','Quality review','Assessed standing'])+'<p class="small-note">Assessed standing depends on evaluation. Applying does not guarantee certification or work.</p></div></section>'
  after='<section class="section-band"><div class="wrap content-section standing" id="standing"><p class="eyebrow">CAPABILITY, SUPPORTED BY EVIDENCE</p><h2 data-core>Standing based on what you can deliver.</h2><p data-core>Your experience, completed project results and professional discussion inform evaluation for your chosen role. Relevant opportunities depend on capability, availability and client requirements.</p></div></section>'
 else:
  rows=[('Demonstrating capability','Independent assessment can help present relevant experience and evidence.'),('Finding relevant opportunities','Matching considers verified capabilities and client requirements.'),('Adding specialist capacity','Explore expertise for an agreed requirement, subject to availability.'),('Retaining your identity','Keep your firm’s identity when you pursue opportunities through OptimIQ.')]
  before='<section class="section-band"><div class="wrap content-section" id="challenges"><p class="eyebrow">YOUR CHALLENGES, IN CONTEXT</p><h2 data-core>A partnership shaped around your practice.</h2><div class="challenge-list">'+''.join(f'<article><h3 data-core>{t}</h3><p data-core>{s}</p></article>' for t,s in rows)+'</div></div></section>'
  after='<section class="section-band"><div class="wrap content-section" id="partnership-process"><p class="eyebrow">A CLEAR PATH FORWARD</p><h2 data-core>From first conversation to collaboration.</h2>'+journey(['Registration','Assessment','Opportunity matching','Delivery and collaboration'])+'<p class="section-intro" data-core>Assessed firms become eligible for introductions to pre-qualified projects, subject to client demand. Delivery arrangements and commercial terms are agreed for each engagement.</p></div></section>'
 body=hero+video(a,'../')+before+'<div class="wrap tool-section">'+calculator(a,a)+'</div>'+after+'<section class="wrap form-section">'+form(a,a)+'</section>'+faq(a)+guide(a)
 folder=ROOT/d['route'];folder.mkdir(exist_ok=True);(folder/'index.html').write_text(shell(a,body),encoding='utf-8')
for a in A:build_audience(a)
build_home()
(ROOT/'site-config.js').write_text('window.OptimIQConfig = '+json.dumps(C,ensure_ascii=False,separators=(',',':'))+';\n',encoding='utf-8')
for a in A:
 folder=ROOT/(A[a]['route']+'-form');folder.mkdir(exist_ok=True);target='../'+A[a]['route']+'/'+REVIEW_Q+'#'+A[a]['formAnchor']
 (folder/'index.html').write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta http-equiv="refresh" content="0;url={target}"><title>Continue to OptimIQ</title></head><body><p><a href="{target}">Continue to the short {e(A[a]["name"].lower())} form</a></p></body></html>',encoding='utf-8')
for a in A:
 html=(ROOT/A[a]['route']/'index.html').read_text(encoding='utf-8')
 core=' '.join(re.sub('<[^>]+>','',s) for s in re.findall(r'<(?:h1|h2|h3|p|strong) data-core>(.*?)</(?:h1|h2|h3|p|strong)>',html))
 print(a,'core narrative words:',len(core.split()))
print('Built homepage, three audience pages and three preview legacy navigation routes.')
